package com.bank.aqecfg.model;

// A profile of the job's data: the executor memory and the biggest single key.
public class JobProfile {
    private final long executorMemoryBytes;
    private final long largestSingleKeyBytes; // a single join/group key's data size

    public JobProfile(long executorMemoryBytes, long largestSingleKeyBytes) {
        this.executorMemoryBytes = executorMemoryBytes;
        this.largestSingleKeyBytes = largestSingleKeyBytes;
    }
    public long getExecutorMemoryBytes() { return executorMemoryBytes; }
    public long getLargestSingleKeyBytes() { return largestSingleKeyBytes; }
}
