package com.bank.aqecfg.config;

import com.bank.aqecfg.model.JobProfile;
import java.util.logging.Logger;

// Validates an AQE config against a job profile and flags the three pitfalls.
public class AqeValidator {
    private static final Logger log = Logger.getLogger(AqeValidator.class.getName());

    public void validate(AqeConfig cfg, JobProfile job) {
        // Pitfall 1: assuming AQE is enabled.
        if (!cfg.adaptiveEnabled) {
            log.severe("PITFALL 1: spark.sql.adaptive.enabled is OFF — "
                    + "coalescing, skew handling, and dynamic joins are ALL inactive");
            return; // nothing else applies
        }
        log.info(() -> "AQE active: coalesce=" + cfg.coalesceEnabled
                + ", skewJoin=" + cfg.skewJoinEnabled);

        // Pitfall 2: changing thresholds blindly (broadcast too high for memory).
        // A safe rule of thumb: broadcast side should be well under executor memory.
        if (cfg.broadcastThreshold > job.getExecutorMemoryBytes() / 4) {
            log.warning(() -> "PITFALL 2: broadcastThreshold " + cfg.broadcastThreshold
                    + "B is large vs executor memory " + job.getExecutorMemoryBytes()
                    + "B — risk of OOM when broadcasting");
        }
        if (cfg.advisoryPartitionSize < 8_000_000) {
            log.warning(() -> "PITFALL 2: advisoryPartitionSize "
                    + cfg.advisoryPartitionSize + "B is very small — recreates tiny-task overhead");
        }

        // Pitfall 3: assuming AQE solves ALL skew.
        // If a single key exceeds the skew threshold, splitting cannot balance it.
        if (cfg.skewJoinEnabled && job.getLargestSingleKeyBytes() > cfg.skewThresholdBytes) {
            log.warning(() -> "PITFALL 3: largest single key "
                    + job.getLargestSingleKeyBytes() + "B exceeds skew threshold — "
                    + "AQE split cannot balance ONE key; use manual SALTING");
        }
    }
}
