package com.bank.aqecfg;

import com.bank.aqecfg.config.*;
import com.bank.aqecfg.model.JobProfile;
import java.util.logging.*;

public class AqeConfigDemo {
    private static final Logger log = Logger.getLogger(AqeConfigDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new AqeCfgLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        JobProfile job = new JobProfile(
            8L * 1024 * 1024 * 1024,   // 8 GB executor memory
            500_000_000L);             // a mega-account single key = 500 MB

        log.info("=== Config A: AQE accidentally OFF ===");
        new AqeValidator().validate(new AqeConfig(
            false, true, true, 67_108_864, 10_485_760, 5, 268_435_456), job);

        log.info("=== Config B: broadcast threshold set too high + tiny advisory ===");
        new AqeValidator().validate(new AqeConfig(
            true, true, true, 4_000_000, 4_000_000_000L, 5, 268_435_456), job);

        log.info("=== Config C: sensible config, but mega-key still needs salting ===");
        new AqeValidator().validate(new AqeConfig(
            true, true, true, 67_108_864, 10_485_760, 5, 268_435_456), job);
    }
}

